:root {
  --color-bg: #fff8ed;
  --color-border: #d4822a;
  --color-header-bg: #d4822a;
  --color-header-text: #ffffff;
  --color-latin: #f5c98a;
  --color-tag-bg: #ffffff;
  --color-tag-text: #d4822a;
  --color-body-bg: #fff8ed;
  --color-label: #a05c1a;
  --color-value: #3b2008;
  --color-footer-bg: #f5e2c4;
  --color-footer-text: #a05c1a;
  --color-row-border: #f0cfa0;
}

.seed-packet {
  display: flex;
  flex-direction: column;
  width: 280px;
  border: 3px solid var(--color-border);
  border-radius: 14px;
  overflow: hidden;
  background: var(--color-bg);
  margin: 40px auto;
}

.packet-header {
  background: var(--color-header-bg);
  padding: 14px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.packet-tag {
  background: var(--color-tag-bg);
  color: var(--color-tag-text);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 20px;
  padding: 2px 8px;
  align-self: flex-start;
}

.flower-name {
  color: var(--color-header-text);
  font-size: 22px;
  font-weight: 800;
  margin: 0;
  line-height: 1.1;
}

.latin-name {
  color: var(--color-latin);
  font-size: 12px;
  font-style: italic;
  margin: 0;
}

.packet-body {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--color-body-bg);
}

.flower-icon {
  font-size: 52px;
  margin: 0;
  line-height: 1;
  flex-shrink: 0;
}

.grow-info {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--color-row-border);
  font-size: 13px;
}

.info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.info-label {
  color: var(--color-label);
  font-weight: 600;
}

.info-value {
  color: var(--color-value);
  font-weight: 700;
}

.packet-footer {
  background: var(--color-footer-bg);
  padding: 8px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 2px dashed var(--color-border);
}

.lot-code {
  color: var(--color-footer-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.exp-date {
  color: var(--color-footer-text);
  font-size: 11px;
  font-weight: 600;
}
